/**
 * RepairCard — Standard-density card for the week calendar view.
 *
 * Shows: customer name, bicycle model, status badge (STATUS_COLORS),
 * assigned worker name, and pickup day indicator when applicable.
 * Card body click navigates to repair detail page.
 */

import { useNavigate } from 'react-router-dom'
import { User, Calendar } from 'lucide-react'
import type { RepairDetailWithCustomer } from '../types.js'
import { STATUS_COLORS } from '../types.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface WorkerOption {
  id: string
  name: string
}

interface RepairCardProps {
  repair: RepairDetailWithCustomer
  workers: WorkerOption[]
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function getWorkerName(assignedTo: string | null, workers: WorkerOption[]): string {
  if (!assignedTo) return 'Unassigned'
  const worker = workers.find((w) => w.id === assignedTo)
  return worker?.name ?? 'Unknown'
}

function formatStatus(status: RepairDetailWithCustomer['status']): string {
  return status.replace('_', ' ').replace(/\b\w/g, (c) => c.toUpperCase())
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function RepairCard({ repair, workers }: RepairCardProps) {
  const navigate = useNavigate()

  const handleClick = () => {
    navigate(`/repairs/${repair.id}`)
  }

  return (
    <div
      role="link"
      tabIndex={0}
      onClick={handleClick}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault()
          handleClick()
        }
      }}
      className={`group cursor-pointer rounded-lg border bg-card p-3 transition-colors hover:bg-muted/50 hover:border-primary/50 ${STATUS_COLORS[repair.status].split(' ')[0]}/10`}
    >
      {/* Status Badge */}
      <div className="mb-2">
        <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${STATUS_COLORS[repair.status]}`}>
          {formatStatus(repair.status)}
        </span>
      </div>

      {/* Customer Name */}
      <div className="text-sm font-semibold text-foreground mb-1">
        {repair.customerName || '—'}
      </div>

      {/* Bicycle Info */}
      <div className="text-xs text-muted-foreground mb-2">
        {repair.bicycleBrand} {repair.bicycleModel}
        {repair.bicycleColor ? ` · ${repair.bicycleColor}` : ''}
      </div>

      {/* Assigned Worker */}
      <div className="flex items-center gap-1.5 text-xs text-muted-foreground mb-2">
        <User size={12} />
        {getWorkerName(repair.assignedTo, workers)}
      </div>

      {/* Pickup Day Indicator */}
      {repair.pickupDate != null && (
        <div className="flex items-center gap-1.5 text-xs">
          <span className="inline-block w-2 h-2 rounded-full bg-blue-500" />
          <span className="text-muted-foreground flex items-center gap-1">
            <Calendar size={10} />
            pickup scheduled
          </span>
        </div>
      )}
    </div>
  )
}

/**
 * Repair feature API client.
 */

import type {
  RepairDetail,
  RepairDetailWithCustomer,
  CustomerWithBicycles,
} from './types.js'

// ---------------------------------------------------------------------------
// Types for request/response shapes
// ---------------------------------------------------------------------------

export interface PaginatedRepairs {
  repairs: RepairDetailWithCustomer[]
  total: number
  page: number
  pageSize: number
  totalPages: number
}

interface RepairIntakeInput {
  customerMode: 'existing' | 'new'
  existingCustomerId?: string
  newCustomer?: {
    firstName?: string
    lastName?: string
    companyName?: string
    phone: string
    email?: string
  }
  bicycleMode: 'select_existing' | 'create_new'
  existingBicycleId?: string
  newBicycle?: {
    brand: string
    model: string
    color: string
  }
  customerNotes: string
  plannedDate?: number | null
  pickupDate?: number | null
}

interface StatusTransitionInput {
  targetStatus: RepairDetail['status']
  holdReason?: 'waiting_parts' | 'awaiting_customer_approval' | 'other'
  holdReasonNote?: string
}

interface NotesUpdateInput {
  customerNotes?: string | null
  internalNotes?: string | null
  plannedDate?: number | null
  pickupDate?: number | null
}

// ---------------------------------------------------------------------------
// API Functions
// ---------------------------------------------------------------------------

/** Create a new repair via the intake flow. */
export async function createRepair(input: RepairIntakeInput): Promise<RepairDetail> {
  const response = await fetch('/api/repairs', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to create repair' }))
    throw new Error(error.error || 'Failed to create repair')
  }

  return response.json()
}

/** Get a single repair by ID. */
export async function getRepair(id: string): Promise<RepairDetail> {
  const response = await fetch(`/api/repairs/${id}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repair')
  }

  return response.json()
}

/** Transition a repair's status. */
export async function transitionRepairStatus(id: string, input: StatusTransitionInput): Promise<RepairDetail> {
  const response = await fetch(`/api/repairs/${id}/transition`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to transition status' }))
    throw new Error(error.error || 'Failed to transition status')
  }

  return response.json()
}

/** Update repair notes. */
export async function updateRepairNotes(id: string, input: NotesUpdateInput): Promise<RepairDetail> {
  const response = await fetch(`/api/repairs/${id}/notes`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to update notes' }))
    throw new Error(error.error || 'Failed to update notes')
  }

  return response.json()
}

/** Get a customer with their bicycles for intake selection. */
export async function getCustomerWithBicycles(customerId: string): Promise<CustomerWithBicycles> {
  const response = await fetch(`/api/repairs/customers/${customerId}`)

  if (!response.ok) {
    throw new Error('Failed to fetch customer with bicycles')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// Timer API — POST /repairs/:id/timer/start & stop
// ---------------------------------------------------------------------------

export interface WorkLog {
  id: string
  repairId: string
  userId: string
  startedAt: number | null
  endedAt: number | null
  durationMs?: number
}

/** Start a manual work timer for a repair. Returns the created work log. */
export async function startWorkTimer(repairId: string, userId: string): Promise<WorkLog> {
  const response = await fetch(`/api/repairs/${repairId}/timer/start`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ userId }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to start timer' }))
    throw new Error(error.error || 'Failed to start work timer')
  }

  return response.json()
}

/** Stop an active work timer session. Returns the updated work log with duration. */
export async function stopWorkTimer(repairId: string, workLogId: string): Promise<WorkLog> {
  const response = await fetch(`/api/repairs/${repairId}/timer/stop`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ workLogId }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to stop timer' }))
    throw new Error(error.error || 'Failed to stop work timer')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// Repair List API — GET /repairs
// ---------------------------------------------------------------------------

interface RepairListFilters {
  status?: string
  assignedTo?: string
  pickupDate?: 'today' | 'this_week'
  page?: number
  pageSize?: number
}

/** Get paginated repair list with optional filters. */
export async function getRepairs(filters: RepairListFilters = {}): Promise<PaginatedRepairs> {
  const params = new URLSearchParams()

  if (filters.status) params.set('status', filters.status)
  if (filters.assignedTo === 'unassigned') params.set('assignedTo', 'unassigned')
  else if (filters.assignedTo) params.set('assignedTo', filters.assignedTo)
  if (filters.pickupDate) params.set('pickupDate', filters.pickupDate)
  params.set('page', String(filters.page ?? 1))
  params.set('pageSize', String(filters.pageSize ?? 20))

  const response = await fetch(`/api/repairs?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repairs list')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// Payment Completion API — POST /repairs/:id/complete
// ---------------------------------------------------------------------------

export interface RepairPaymentMethod {
  method: 'cash' | 'card'
  amount: number
}

export interface CompleteRepairInput {
  payments: RepairPaymentMethod[]
}

export interface CompleteRepairResult {
  repair: {
    id: string
    bicycleId: string
    assignedTo: string | null
    status: 'completed'
    customerNotes: string | null
    internalNotes: string | null
    holdReason: string | null
    holdReasonNote: string | null
    plannedDate: number | null
    pickupDate: number | null
    completedAt: number | null
    createdAt: number
  }
  sale: {
    id: string
    saleNumber: string
    customerId: string | null
    sourceType: 'direct_sale' | 'repair' | 'customer_order' | 'backorder'
    sourceId: string | null
    status: 'completed' | 'voided'
    subtotalNet: number
    vatTotal: number
    totalGross: number
  }
  payments: Array<{
    id: string
    method: 'cash' | 'card' | 'bank_transfer'
    amount: number
  }>
  stockMovements: Array<{
    id: string
    partId: string
    quantityDelta: number
    reason: string
    referenceType: string
    referenceId: string
  }>
}

/**
 * Complete a repair with payment data (single or split methods).
 *
 * Atomic transaction: validates → deducts stock → creates linked sale → marks completed.
 */
export async function completeRepairPayment(
  repairId: string,
  input: CompleteRepairInput,
): Promise<CompleteRepairResult> {
  const response = await fetch(`/api/repairs/${repairId}/complete`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Payment completion failed' }))
    throw new Error(error.error || `Failed to complete repair (status ${response.status})`)
  }

  return response.json() as Promise<CompleteRepairResult>
}

// ---------------------------------------------------------------------------
// Week Calendar API — GET /repairs?from=&to=&statusIn=
// ---------------------------------------------------------------------------

/** Active statuses shown on the week calendar */
const ACTIVE_STATUSES = ['in_progress', 'on_hold', 'verified', 'ready'] as const

/**
 * Fetch repairs for a date range (week). Filters by active statuses only.
 *
 * @param from — Inclusive epoch-ms lower bound
 * @param to — Inclusive epoch-ms upper bound
 */
export async function getRepairsForWeek(from: number, to: number): Promise<PaginatedRepairs> {
  const statusIn = ACTIVE_STATUSES.join(',')
  const params = new URLSearchParams()
  params.set('from', String(from))
  params.set('to', String(to))
  params.set('statusIn', statusIn)
  params.set('page', '1')
  params.set('pageSize', '100') // calendar needs all repairs for the week

  const response = await fetch(`/api/repairs?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repairs for week')
  }

  return response.json()
}

/**
 * useRepairsForWeek — Data hook for the week calendar view.
 *
 * Fetches active repairs for a 7-day range (Mon–Sun) and provides
 * prev/next/today navigation. Returns epoch-ms boundaries so that
 * the UI can distribute repair cards into day columns.
 */

import { useState, useEffect, useCallback } from 'react'
import type { RepairDetailWithCustomer } from '../types.js'
import { getRepairsForWeek } from '../api.js'

// ---------------------------------------------------------------------------
// Week boundary helpers (Mon–Sun, local time)
// ---------------------------------------------------------------------------

/** Get Monday 00:00:00.000 of the week containing `date` */
function mondayOf(date: Date): number {
  const d = new Date(date)
  const day = d.getDay() // 0=Sun, 1=Mon ...
  const diffToMonday = day === 0 ? -6 : 1 - day
  d.setDate(d.getDate() + diffToMonday)
  d.setHours(0, 0, 0, 0)
  return d.getTime()
}

// ---------------------------------------------------------------------------
// Hook interface
// ---------------------------------------------------------------------------

export interface UseRepairsForWeekOptions {
  /** Optional anchor date. Defaults to today. */
  initialDate?: Date
}

export interface UseRepairsForWeekReturn {
  repairs: RepairDetailWithCustomer[]
  weekStart: number // Monday 00:00:00.000 (epoch ms)
  weekEnd: number   // Sunday 23:59:59.999 (epoch ms)
  isLoading: boolean
  error: string | null
  goPrev: () => void
  goNext: () => void
  goToday: () => void
}

/**
 * Fetches repairs for a week range and provides navigation controls.
 */
export function useRepairsForWeek(options?: UseRepairsForWeekOptions): UseRepairsForWeekReturn {
  const anchorDate = options?.initialDate ?? new Date()

  // Track the current Monday to enable prev/next navigation
  const [weekMonday, setWeekMonday] = useState<number>(() => mondayOf(anchorDate))

  const [repairs, setRepairs] = useState<RepairDetailWithCustomer[]>([])
  const [isLoading, setIsLoading] = useState<boolean>(true)
  const [error, setError] = useState<string | null>(null)

  // Compute week boundaries from the current Monday anchor
  const weekStart = weekMonday
  const weekEnd = (() => {
    const sun = new Date(weekMonday)
    sun.setDate(sun.getDate() + 6)
    sun.setHours(23, 59, 59, 999)
    return sun.getTime()
  })()

  // Fetch repairs whenever the week range changes
  useEffect(() => {
    let cancelled = false

    const fetchRepairs = async () => {
      setIsLoading(true)
      setError(null)

      try {
        const result = await getRepairsForWeek(weekStart, weekEnd)
        if (!cancelled) {
          setRepairs(result.repairs)
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : 'Failed to fetch repairs')
          setRepairs([])
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false)
        }
      }
    }

    fetchRepairs()

    return () => {
      cancelled = true
    }
  }, [weekStart, weekEnd])

  // Navigation handlers — shift the Monday anchor by ±7 days
  const goPrev = useCallback(() => {
    setWeekMonday((prev) => prev - 7 * 24 * 60 * 60 * 1000)
  }, [])

  const goNext = useCallback(() => {
    setWeekMonday((prev) => prev + 7 * 24 * 60 * 60 * 1000)
  }, [])

  const goToday = useCallback(() => {
    setWeekMonday(mondayOf(new Date()))
  }, [])

  return { repairs, weekStart, weekEnd, isLoading, error, goPrev, goNext, goToday }
}

/**
 * Date anchor utility.
 *
 * Resolves a repair's display date for calendar placement:
 * - Primary: plannedDate (epoch ms)
 * - Fallback: createdAt when plannedDate is null/undefined
 */

export interface DateAnchorInput {
  plannedDate: number | null | undefined
  createdAt: number
}

/**
 * Returns the epoch-ms timestamp to anchor a repair card on the calendar.
 * Uses plannedDate if present; falls back to createdAt.
 */
export function getDateAnchor(input: DateAnchorInput): number {
  return input.plannedDate ?? input.createdAt
}

/**
 * RepairCard — Component tests.
 *
 * Verifies:
 * - Renders customer name, bicycle model, status badge, assigned worker
 * - Status badge uses STATUS_COLORS mapping
 * - Card body click navigates to repair detail page
 * - Pickup day indicator shown when pickupDate is set
 * - Pickup day indicator hidden when pickupDate is null
 */

import { describe, it, expect } from 'vitest'
import { render, screen, fireEvent } from '@testing-library/react'
import { MemoryRouter } from 'react-router-dom'
import type { RepairDetailWithCustomer } from '../../types.js'
import { RepairCard } from '../RepairCard.js'

// ---------------------------------------------------------------------------
// Test fixtures
// ---------------------------------------------------------------------------

function createRepair(overrides?: Partial<RepairDetailWithCustomer>): RepairDetailWithCustomer {
  return {
    id: 'repair-001',
    assignedTo: null,
    status: 'in_progress',
    customerNotes: null,
    internalNotes: null,
    holdReason: null,
    holdReasonNote: null,
    plannedDate: 1706832000000, // Feb 2, 2024
    pickupDate: null,
    completedAt: null,
    createdAt: 1706745600000,
    customerName: 'Jane Doe',
    bicycleBrand: 'Trek',
    bicycleModel: 'Domane SL',
    bicycleColor: 'blue',
    ...overrides,
  }
}

function renderCard(repair?: RepairDetailWithCustomer) {
  const r = repair ?? createRepair()
  return render(
    <MemoryRouter>
      <RepairCard repair={r} workers={[]} />
    </MemoryRouter>
  )
}

// ---------------------------------------------------------------------------
// Tests: Basic rendering
// ---------------------------------------------------------------------------

describe('RepairCard — basic rendering', () => {
  it('renders customer name', () => {
    renderCard()
    expect(screen.getByText('Jane Doe')).toBeInTheDocument()
  })

  it('renders bicycle brand and model', () => {
    renderCard()
    expect(screen.getByText(/Trek Domane SL/)).toBeInTheDocument()
  })

  it('renders status badge with correct text', () => {
    renderCard()
    expect(screen.getByText(/in progress/i)).toBeInTheDocument()
  })

  it('renders assigned worker name when assignedTo is set and workers provided', () => {
    const repair = createRepair({ assignedTo: 'worker-01' })
    render(
      <MemoryRouter>
        <RepairCard repair={repair} workers={[{ id: 'worker-01', name: 'Bob Smith' }]} />
      </MemoryRouter>
    )
    expect(screen.getByText('Bob Smith')).toBeInTheDocument()
  })

  it('renders "Unassigned" when assignedTo is null', () => {
    renderCard()
    expect(screen.getByText('Unassigned')).toBeInTheDocument()
  })
})

// ---------------------------------------------------------------------------
// Tests: Status badge colors
// ---------------------------------------------------------------------------

describe('RepairCard — status badge colors', () => {
  it.each([
    ['intake', 'blue'],
    ['in_progress', 'yellow'],
    ['on_hold', 'orange'],
    ['verified', 'purple'],
    ['ready', 'green'],
  ] as [RepairDetailWithCustomer['status'], string][])(
    'applies %s status color for "%s"',
    (status, expectedColor) => {
      const repair = createRepair({ status })
      renderCard(repair)
      // Check that the badge element contains the expected color class
      const badge = screen.getByText(new RegExp(status.replace('_', ' '), 'i'))
      expect(badge.className).toContain(expectedColor)
    }
  )
})

// ---------------------------------------------------------------------------
// Tests: Card click navigation
// ---------------------------------------------------------------------------

describe('RepairCard — click navigation', () => {
  it('navigates to repair detail page when card body is clicked', async () => {
    render(
      <MemoryRouter initialEntries={['/repairs']}>
        <RepairCard repair={createRepair()} workers={[]} />
      </MemoryRouter>
    )
    const card = screen.getByRole('link')
    fireEvent.click(card)

    // MemoryRouter navigates by changing location — verify the link behavior
    expect(card).toHaveAttribute('tabIndex', '0')
  })
})

// ---------------------------------------------------------------------------
// Tests: Pickup day indicator
// ---------------------------------------------------------------------------

describe('RepairCard — pickup day indicator', () => {
  it('shows pickup indicator when pickupDate is set', () => {
    const repair = createRepair({ pickupDate: 1706918400000 }) // Feb 3, 2024
    render(
      <MemoryRouter>
        <RepairCard repair={repair} workers={[]} />
      </MemoryRouter>
    )
    expect(screen.getByText(/pickup/i)).toBeInTheDocument()
  })

  it('does not show pickup indicator when pickupDate is null', () => {
    renderCard(createRepair({ pickupDate: null }))
    expect(screen.queryByText(/pickup/i)).not.toBeInTheDocument()
  })
})

// ---------------------------------------------------------------------------
// Tests: customerName fallback
// ---------------------------------------------------------------------------

describe('RepairCard — customer name fallback', () => {
  it('renders "—" when customerName is null', () => {
    renderCard(createRepair({ customerName: null }))
    expect(screen.getByText('—')).toBeInTheDocument()
  })
})

/**
 * RepairCalendarView — Week calendar UI for active repairs.
 *
 * 7-column grid (Mon–Sun) distributing repairs into day columns by date anchor.
 * Week navigation header with ← / Today / → and week label.
 */

import { useState, useEffect, useMemo } from 'react'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import type { RepairDetailWithCustomer } from '../types.js'
import { useRepairsForWeek } from '../hooks/useRepairsForWeek.js'
import { getDateAnchor } from '../utils/dateAnchor.js'
import { RepairCard } from './RepairCard.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface WorkerOption {
  id: string
  name: string
}

interface DayColumn {
  dayLabel: string // Mon, Tue, ... Sun
  dateStr: string  // "5 Feb" format
  epochMs: number  // start of that day (00:00:00)
  repairs: RepairDetailWithCustomer[]
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const DAY_LABELS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'] as const

/** Get the day-of-week index (0=Mon, 6=Sun) for a given epoch-ms */
function getDayIndex(epochMs: number): number {
  const date = new Date(epochMs)
  const dow = date.getDay() // 0=Sun, 1=Mon ...
  return dow === 0 ? 6 : dow - 1 // Convert to Mon=0 ... Sun=6
}

/** Format epoch-ms as "5 Feb" (day + short month) */
function formatDateShort(epochMs: number): string {
  const date = new Date(epochMs)
  return date.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })
}

/** Format epoch-ms as "May 25 – May 31" for week label */
function formatWeekLabel(weekStart: number, _weekEnd: number): string {
  const start = new Date(weekStart)
  const end = new Date(_weekEnd)
  return `${start.toLocaleDateString('en-GB', { day: 'numeric', month: 'long' })} – ${end.toLocaleDateString('en-GB', { day: 'numeric', month: 'long' })}`
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function RepairCalendarView() {
  const { repairs, weekStart, weekEnd, isLoading, goPrev, goNext, goToday } = useRepairsForWeek()

  // Fetch workers list for worker name resolution
  const [workers, setWorkers] = useState<WorkerOption[]>([])

  useEffect(() => {
    fetch('/api/users')
      .then((r) => r.json())
      .then((data: WorkerOption[]) => setWorkers(data))
      .catch(() => setWorkers([]))
  }, [])

  // Build day columns and distribute repairs
  const dayColumns = useMemo(() => {
    const columns: DayColumn[] = []

    for (let i = 0; i < 7; i++) {
      const dayEpoch = weekStart + i * 24 * 60 * 60 * 1000
      columns.push({
        dayLabel: DAY_LABELS[i],
        dateStr: formatDateShort(dayEpoch),
        epochMs: dayEpoch,
        repairs: [],
      })
    }

    // Distribute repairs into day columns by date anchor
    for (const repair of repairs) {
      const anchor = getDateAnchor({ plannedDate: repair.plannedDate, createdAt: repair.createdAt })

      // Only place in column if it falls within the displayed week range [weekStart .. weekEnd]
      if (anchor >= weekStart && anchor <= weekEnd) {
        const dayIndex = getDayIndex(anchor)
        columns[dayIndex].repairs.push(repair)
      }
    }

    return columns
  }, [repairs, weekStart])

  const weekLabel = formatWeekLabel(weekStart, weekEnd)

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12" role="status">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    )
  }

  return (
    <div className="p-6">
      {/* Week Navigation Header */}
      <div className="flex items-center justify-between mb-6">
        <h1 className="text-2xl font-bold text-foreground">Repair Calendar</h1>
        <div className="flex items-center gap-3">
          <button
            onClick={goPrev}
            aria-label="Previous week"
            className="p-2 rounded-lg border hover:bg-muted transition-colors"
          >
            <ChevronLeft size={18} />
          </button>
          <button
            onClick={goToday}
            aria-label="Today"
            className="px-3 py-1.5 text-sm font-medium rounded-lg border hover:bg-muted transition-colors"
          >
            Today
          </button>
          <button
            onClick={goNext}
            aria-label="Next week"
            className="p-2 rounded-lg border hover:bg-muted transition-colors"
          >
            <ChevronRight size={18} />
          </button>
        </div>
      </div>

      {/* Week Label */}
      <div className="mb-4 text-sm font-medium text-muted-foreground">
        {weekLabel}
      </div>

      {/* 7-Day Grid */}
      <div className="grid grid-cols-7 gap-3">
        {dayColumns.map((column) => (
          <DayColumn key={column.epochMs} column={column} workers={workers} />
        ))}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Sub-component — Single Day Column
