/**
 * Combobox — A generic searchable dropdown built on Radix Popover.
 *
 * Provides:
 * - Search input with debounce (managed by caller via `onSearchChange`)
 * - Floating results list with keyboard navigation
 * - Loading and empty states
 * - Selected item display with optional clear button
 *
 * Usage:
 * ```tsx
 * <Combobox<PostalCodeResult>
 *   items={results}
 *   isLoading={isLoading}
 *   value={selectedItem}
 *   onValueChange={(item) => setSelected(item)}
 *   onSearchChange={(query) => setSearch(query)}
 *   placeholder="Search..."
 *   renderOption={(item) => <span>{item.name}</span>}
 * />
 * ```
 */

import { useState, useRef, useEffect, useCallback } from 'react'
import { cn } from '@/shared/lib/utils.js'
import { X, Loader2 } from 'lucide-react'
import type { ComponentPropsWithoutRef, KeyboardEvent as ReactKeyboardEvent } from 'react'

// ---------------------------------------------------------------------------
// Props
// ---------------------------------------------------------------------------

export interface ComboboxProps<T> extends Omit<ComponentPropsWithoutRef<'div'>, 'onValueChange'> {
  /** Available items to display in the dropdown. */
  items: T[]
  /** Whether a search is currently in progress. */
  isLoading: boolean
  /** Currently selected item (null = unselected). */
  value: T | null
  /** Called when user selects an item. Pass null to clear selection. */
  onValueChange: (value: T | null) => void
  /** Called with the current search query string as user types. */
  onSearchChange: (query: string) => void
  /** Placeholder text for the input field. */
  placeholder?: string
  /** Render function for each dropdown item. Receives the full item object. */
  renderOption: (item: T, index: number) => React.ReactNode
  /** Whether the combobox is disabled. Shows a read-only label when true and has a value. */
  disabled?: boolean
}

// ---------------------------------------------------------------------------
// Component — Combobox
// ---------------------------------------------------------------------------

export function Combobox<T extends { [key: string]: unknown }>({
  items,
  isLoading,
  value,
  onValueChange,
  onSearchChange,
  placeholder = 'Search...',
  renderOption,
  disabled = false,
  className,
}: ComboboxProps<T>) {
  const [isOpen, setIsOpen] = useState(false)
  const [highlightedIndex, setHighlightedIndex] = useState(-1)

  // Local search query state — drives the input value directly.
  // onSearchChange is called as a side-effect for parent integration.
  const [searchQuery, setSearchQuery] = useState('')

  // Local controlled input — synced with value state.
  // When a selection is made, the display shows it and the input area becomes read-only.
  // When cleared, we reset to search mode.
  const [displayValue, setDisplayValue] = useState<string>('')

  // Keep displayValue in sync with external value prop.
  useEffect(() => {
    if (value) {
      setDisplayValue(String(value.name))
    } else {
      setDisplayValue('')
    }
  }, [value])

  // Refs for focus management and click-outside detection.
  const containerRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const listRef = useRef<HTMLUListElement>(null)

  // Reset highlight when items change (new search results).
  useEffect(() => {
    setHighlightedIndex(-1)
  }, [items])

  /** Close the dropdown. */
  const close = useCallback(() => {
    setIsOpen(false)
    setHighlightedIndex(-1)
  }, [])

  /** Open the dropdown and focus the input. */
  const open = useCallback(() => {
    if (!disabled) {
      setIsOpen(true)
      // If we have a value, select it all so user can type over immediately.
      setTimeout(() => {
        inputRef.current?.focus()
        if (displayValue && isOpen) {
          inputRef.current?.select()
        }
      }, 0)
    }
  }, [disabled, displayValue, isOpen])

  /** Handle selecting an item. */
  const handleSelect = useCallback((item: T) => {
    onValueChange(item)
    close()
  }, [onValueChange, close])

  /** Clear selection and reopen for a new search. */
  const handleClear = useCallback((e: React.MouseEvent) => {
    e.stopPropagation()
    setSearchQuery('')
    onValueChange(null)
    close()
    // Reopen so user can immediately type again.
    setTimeout(() => inputRef.current?.focus(), 0)
  }, [onValueChange, close])

  /** Handle keyboard navigation in the dropdown. */
  const handleKeyDown = useCallback((e: ReactKeyboardEvent<HTMLInputElement>) => {
    if (!isOpen) return

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setHighlightedIndex((prev) => Math.min(prev + 1, items.length - 1))
        break

      case 'ArrowUp':
        e.preventDefault()
        setHighlightedIndex((prev) => Math.max(prev - 1, 0))
        break

      case 'Enter': {
        e.preventDefault()
        if (highlightedIndex >= 0 && highlightedIndex < items.length) {
          handleSelect(items[highlightedIndex])
        } else if (!value && items.length > 0) {
          // Select first item when nothing is selected and there are results.
          handleSelect(items[0])
        }
        break
      }

      case 'Escape':
        e.preventDefault()
        close()
        break

      default:
        break
    }
  }, [isOpen, highlightedIndex, items.length, value, handleSelect, close])

  /** Handle input blur — close dropdown if focus leaves the container. */
  const handleBlur = useCallback((e: React.FocusEvent<HTMLInputElement>) => {
    // Check if focus is moving to a descendant (the results list).
    const relatedTarget = e.relatedTarget as HTMLElement | null
    if (relatedTarget?.closest('[data-combobox-list]')) return
    close()
  }, [close])

  // Scroll highlighted item into view.
  useEffect(() => {
    if (highlightedIndex >= 0 && listRef.current) {
      const el = listRef.current.children[highlightedIndex] as HTMLElement | null
      el?.scrollIntoView({ block: 'nearest' })
    }
  }, [highlightedIndex])

  // -----------------------------------------------------------------------
  // Render — selected display (when not editing) or input (when open/searching)
  // -----------------------------------------------------------------------

  const hasValue = value !== null && displayValue.length > 0

  if (disabled && hasValue) {
    return (
      <div className={cn('text-sm text-muted-foreground', className)}>
        {displayValue}
      </div>
    )
  }

  return (
    <div ref={containerRef} className={cn(className)}>
      {/* Input wrapper */}
      <div
        role="combobox"
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        onClick={open}
        className={cn(
          'flex h-10 w-full items-center gap-2 rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-within:outline-none focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2 cursor-text',
        )}
      >
        {/* Selected value display or search input */}
        {hasValue ? (
          <div className="flex flex-1 items-center gap-1.5">
            <span>{displayValue}</span>
            {!disabled && (
              <button
                type="button"
                onClick={handleClear}
                className="ml-auto p-0.5 rounded-full hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
                tabIndex={-1}
              >
                <X className="h-3 w-3" />
                <span className="sr-only">Clear selection</span>
              </button>
            )}
          </div>
        ) : (
          <input
            ref={inputRef}
            type="text"
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value)
              onSearchChange(e.target.value)
            }}
            onKeyDown={handleKeyDown}
            onBlur={handleBlur}
            placeholder={placeholder}
            className="flex-1 bg-transparent outline-none text-sm placeholder:text-muted-foreground disabled:cursor-not-allowed"
            disabled={disabled}
          />
        )}

        {/* Loading indicator */}
        {isLoading && (
          <Loader2 className="h-4 w-4 animate-spin text-muted-foreground shrink-0" />
        )}
      </div>

      {/* Dropdown results */}
      {isOpen && !disabled && (
        <ul
          ref={listRef}
          data-combobox-list
          role="listbox"
          className="absolute z-50 mt-1 max-h-64 w-full overflow-y-auto rounded-md border bg-popover text-popover-foreground shadow-lg outline-none"
        >
          {isLoading && items.length === 0 ? (
            <li className="flex items-center gap-2 px-3 py-2 text-sm text-muted-foreground">
              <Loader2 className="h-4 w-4 animate-spin" />
              Searching...
            </li>
          ) : items.length === 0 ? (
            <li className="px-3 py-2 text-sm text-muted-foreground">No results</li>
          ) : (
            items.map((item, index) => (
              <li
                key={String(item.code ?? item.name)} // Use unique identifier if available.
                role="option"
                aria-selected={index === highlightedIndex}
                onMouseDown={(e) => {
                  e.preventDefault() // Prevent focus from leaving input (which triggers blur/close before React processes click)
                  handleSelect(item)
                }}
                className={cn(
                  'px-3 py-2 text-sm cursor-pointer transition-colors',
                  index === highlightedIndex && 'bg-accent text-accent-foreground'
                )}
              >
                {renderOption(item, index)}
              </li>
            ))
          )}
        </ul>
      )}
    </div>
  )
}

/**
 * useRepairsForWeek — Unit tests.
 *
 * Tests:
 * - Week range computation from a given date (Mon-Sun)
 * - prev/next navigation produces correct new ranges
 * - "Today" resets to current week
 * - API call made with correct params on mount and navigation change
 */

import { describe, it, expect, vi, afterEach } from 'vitest'
import { renderHook, act, waitFor } from '@testing-library/react'
import type { RepairDetailWithCustomer } from '../../types.js'
import type { PaginatedRepairs } from '../../api.js'

// ---------------------------------------------------------------------------
// Mock the API module — must be hoisted to top of file for vi.mock
// ---------------------------------------------------------------------------

const mockGetRepairsForWeek = vi.fn() as ReturnType<typeof vi.fn> & {
  mockResolvedValueOnce: (value: PaginatedRepairs) => void
  mockRejectedValueOnce: (error: Error) => void
}

vi.mock('../../api.js', () => ({
  getRepairsForWeek: (...args: unknown[]) => mockGetRepairsForWeek(...args),
}))

// ---------------------------------------------------------------------------
// Test fixtures
// ---------------------------------------------------------------------------

function createMockRepair(id: string, status: RepairDetailWithCustomer['status'], plannedDate: number | null): RepairDetailWithCustomer {
  return {
    id,
    assignedTo: null,
    status,
    customerNotes: null,
    internalNotes: null,
    holdReason: null,
    holdReasonNote: null,
    plannedDate,
    pickupDate: null,
    completedAt: null,
    createdAt: 1706745600000,
    customerName: 'Test Customer',
    bicycleBrand: 'Trek',
    bicycleModel: 'Domane',
    bicycleColor: 'blue',
  }
}

const mockRepairs: RepairDetailWithCustomer[] = [
  createMockRepair('r1', 'in_progress', 1706832000000),
  createMockRepair('r2', 'on_hold', null),
]

function createPaginatedResponse(repairs: RepairDetailWithCustomer[]): PaginatedRepairs {
  return { repairs, total: repairs.length, page: 1, pageSize: 100, totalPages: 1 }
}

// ---------------------------------------------------------------------------
// Helpers — compute expected week boundaries (Mon-Sun, local time)
// ---------------------------------------------------------------------------

/** Get Monday 00:00:00.000 of the week containing `date` */
function mondayOf(date: Date): number {
  const d = new Date(date)
  const day = d.getDay() // 0=Sun, 1=Mon ...
  const diffToMonday = day === 0 ? -6 : 1 - day
  d.setDate(d.getDate() + diffToMonday)
  d.setHours(0, 0, 0, 0)
  return d.getTime()
}

/** Get Sunday 23:59:59.999 of the week containing `date` */
function sundayEndOf(date: Date): number {
  const mon = mondayOf(date)
  const sun = new Date(mon)
  sun.setDate(sun.getDate() + 6)
  sun.setHours(23, 59, 59, 999)
  return sun.getTime()
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('useRepairsForWeek', () => {
  afterEach(() => {
    vi.resetAllMocks()
  })

  // -- Week range computation --

  it('computes correct week range (Mon-Sun) for a given date', async () => {
    const testDate = new Date(2024, 1, 5) // Feb 5, 2024 — Monday
    const expectedStart = mondayOf(testDate)
    const expectedEnd = sundayEndOf(testDate)

    mockGetRepairsForWeek.mockResolvedValueOnce(createPaginatedResponse(mockRepairs))

    const { result } = renderHook(() => useRepairsForWeek({ initialDate: testDate }))

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    expect(result.current.weekStart).toBe(expectedStart)
    expect(result.current.weekEnd).toBe(expectedEnd)
  })

  it('computes week range for a date mid-week', async () => {
    const testDate = new Date(2024, 1, 8) // Feb 8, 2024 — Thursday
    const expectedStart = mondayOf(testDate)
    const expectedEnd = sundayEndOf(testDate)

    mockGetRepairsForWeek.mockResolvedValueOnce(createPaginatedResponse(mockRepairs))

    const { result } = renderHook(() => useRepairsForWeek({ initialDate: testDate }))

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    expect(result.current.weekStart).toBe(expectedStart)
    expect(result.current.weekEnd).toBe(expectedEnd)
  })

  it('computes week range for a Sunday (belongs to current week)', async () => {
    const testDate = new Date(2024, 1, 4) // Feb 4, 2024 — Sunday
    const expectedStart = mondayOf(testDate)
    const expectedEnd = sundayEndOf(testDate)

    mockGetRepairsForWeek.mockResolvedValueOnce(createPaginatedResponse(mockRepairs))

    const { result } = renderHook(() => useRepairsForWeek({ initialDate: testDate }))

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    expect(result.current.weekStart).toBe(expectedStart)
    expect(result.current.weekEnd).toBe(expectedEnd)
  })

  // -- Navigation --

  it('goPrev navigates to previous week', async () => {
    const testDate = new Date(2024, 1, 5) // Feb 5 — Monday
    mockGetRepairsForWeek.mockResolvedValueOnce(createPaginatedResponse(mockRepairs))

    const { result } = renderHook(() => useRepairsForWeek({ initialDate: testDate }))

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    const firstWeekStart = result.current.weekStart

    // Navigate to previous week
    mockGetRepairsForWeek.mockResolvedValueOnce(createPaginatedResponse([]))
    act(() => {
      result.current.goPrev()
    })

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    const prevWeekStart = result.current.weekStart
    // Previous week Monday should be exactly 7 days earlier
    expect(prevWeekStart).toBe(firstWeekStart - 7 * 24 * 60 * 60 * 1000)
  })

  it('goNext navigates to next week', async () => {
    const testDate = new Date(2024, 1, 5) // Feb 5 — Monday
    mockGetRepairsForWeek.mockResolvedValueOnce(createPaginatedResponse(mockRepairs))

    const { result } = renderHook(() => useRepairsForWeek({ initialDate: testDate }))

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    const firstWeekStart = result.current.weekStart

    // Navigate to next week
    mockGetRepairsForWeek.mockResolvedValueOnce(createPaginatedResponse([]))
    act(() => {
      result.current.goNext()
    })

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    const nextWeekStart = result.current.weekStart
    // Next week Monday should be exactly 7 days later
    expect(nextWeekStart).toBe(firstWeekStart + 7 * 24 * 60 * 60 * 1000)
  })

  it('goToday resets to the current week', async () => {
    // Start with a date in February 2024
    const testDate = new Date(2024, 1, 5) // Feb 5 — Monday
    mockGetRepairsForWeek.mockResolvedValueOnce(createPaginatedResponse(mockRepairs))

    const { result } = renderHook(() => useRepairsForWeek({ initialDate: testDate }))

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    // Navigate forward a few weeks first
    mockGetRepairsForWeek.mockResolvedValueOnce(createPaginatedResponse([]))
    act(() => {
      result.current.goNext()
    })
    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    const futureWeekStart = result.current.weekStart
    expect(futureWeekStart).toBeGreaterThan(mondayOf(testDate))

    // Now go to today — should reset to current week (not Feb 2024)
    mockGetRepairsForWeek.mockResolvedValueOnce(createPaginatedResponse([]))
    act(() => {
      result.current.goToday()
    })

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    const todayWeekStart = mondayOf(new Date())
    expect(result.current.weekStart).toBe(todayWeekStart)
  })

  // -- API calls --

  it('calls API with correct params on mount', async () => {
    const testDate = new Date(2024, 1, 5) // Feb 5 — Monday
    const expectedFrom = mondayOf(testDate)
    const expectedTo = sundayEndOf(testDate)

    mockGetRepairsForWeek.mockResolvedValueOnce(createPaginatedResponse(mockRepairs))

    renderHook(() => useRepairsForWeek({ initialDate: testDate }))

    await waitFor(() => {
      expect(mockGetRepairsForWeek).toHaveBeenCalledWith(expectedFrom, expectedTo)
    })
  })

  it('calls API with new params on navigation', async () => {
    const testDate = new Date(2024, 1, 5) // Feb 5 — Monday
    mockGetRepairsForWeek.mockResolvedValueOnce(createPaginatedResponse(mockRepairs))

    const { result } = renderHook(() => useRepairsForWeek({ initialDate: testDate }))

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    const mountCalls = mockGetRepairsForWeek.mock.calls.length

    // Navigate to next week — should trigger new API call
    mockGetRepairsForWeek.mockResolvedValueOnce(createPaginatedResponse([]))
    act(() => {
      result.current.goNext()
    })

    await waitFor(() => {
      expect(mockGetRepairsForWeek.mock.calls.length).toBeGreaterThan(mountCalls)
    })

    // Verify the new call used different params (next week's range)
    const lastCall = mockGetRepairsForWeek.mock.calls[mockGetRepairsForWeek.mock.calls.length - 1]
    expect(lastCall[0]).not.toBe(mockGetRepairsForWeek.mock.calls[0][0]) // from changed
    expect(lastCall[1]).not.toBe(mockGetRepairsForWeek.mock.calls[0][1]) // to changed
  })

  it('returns repairs data after API resolves', async () => {
    const testDate = new Date(2024, 1, 5)
    mockGetRepairsForWeek.mockResolvedValueOnce(createPaginatedResponse(mockRepairs))

    const { result } = renderHook(() => useRepairsForWeek({ initialDate: testDate }))

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    expect(result.current.repairs).toEqual(mockRepairs)
  })

  it('defaults to today when no initialDate provided', async () => {
    mockGetRepairsForWeek.mockResolvedValueOnce(createPaginatedResponse([]))

    const { result } = renderHook(() => useRepairsForWeek())

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false)
    })

    const todayWeekStart = mondayOf(new Date())
    expect(result.current.weekStart).toBe(todayWeekStart)
  })
})

// Need to import the hook after vi.mock is hoisted
import { useRepairsForWeek } from '../useRepairsForWeek.js'

