/**
 * ReschedulePopover — Component tests.
 *
 * Verifies:
 * - Renders date input and confirm/cancel buttons when open
 * - Does not render anything when closed
 * - Confirm sends PATCH to updateRepairNotes with new plannedDate
 * - Calls onConfirm callback after successful save
 * - Calls onCancel callback when cancel is clicked
 * - Closes on save or cancel
 */

import { describe, it, expect, vi } from 'vitest'
import { render, screen, fireEvent, waitFor } from '@testing-library/react'
import type { RepairDetailWithCustomer } from '../../types.js'
import { ReschedulePopover } from '../ReschedulePopover.js'

// ---------------------------------------------------------------------------
// Mock the API module
// ---------------------------------------------------------------------------

const mockUpdateRepairNotes = vi.fn() as ReturnType<typeof vi.fn> & {
  mockResolvedValueOnce: (value: RepairDetailWithCustomer) => void
}

vi.mock('../../api.js', () => ({
  updateRepairNotes: (...args: unknown[]) => mockUpdateRepairNotes(...args),
}))

// ---------------------------------------------------------------------------
// Test fixtures
// ---------------------------------------------------------------------------

function createRepair(overrides?: Partial<RepairDetailWithCustomer>): RepairDetailWithCustomer {
  return {
    id: 'repair-001',
    assignedTo: null,
    status: 'in_progress',
    customerNotes: null,
    internalNotes: null,
    holdReason: null,
    holdReasonNote: null,
    plannedDate: 1706832000000, // Feb 2, 2024
    pickupDate: null,
    completedAt: null,
    createdAt: 1706745600000,
    customerName: 'Jane Doe',
    bicycleBrand: 'Trek',
    bicycleModel: 'Domane SL',
    bicycleColor: 'blue',
    ...overrides,
  }
}

function renderPopover(
  repair?: RepairDetailWithCustomer,
  props?: { onConfirm?: () => void; onCancel?: () => void },
) {
  const r = repair ?? createRepair()
  return render(
    <ReschedulePopover
      repair={r}
      open={true}
      onConfirm={props?.onConfirm ?? vi.fn()}
      onCancel={props?.onCancel ?? vi.fn()}
    />,
  )
}

// ---------------------------------------------------------------------------
// Tests: Rendering
// ---------------------------------------------------------------------------

describe('ReschedulePopover — rendering', () => {
  it('renders date input when open', () => {
    renderPopover()
    expect(screen.getByRole('textbox')).toBeInTheDocument()
  })

  it('renders confirm button', () => {
    renderPopover()
    expect(screen.getByText(/confirm/i)).toBeInTheDocument()
  })

  it('renders cancel button', () => {
    renderPopover()
    expect(screen.getByText(/cancel/i)).toBeInTheDocument()
  })

  it('pre-fills date input with current plannedDate', () => {
    const repair = createRepair({ plannedDate: 1706832000000 }) // Feb 2, 2024
    renderPopover(repair)
    const input = screen.getByRole('textbox') as HTMLInputElement
    expect(input.value).toBe('2024-02-02')
  })

  it('pre-fills date input with createdAt fallback when plannedDate is null', () => {
    const repair = createRepair({ plannedDate: null, createdAt: 1706745600000 }) // Feb 1, 2024
    renderPopover(repair)
    const input = screen.getByRole('textbox') as HTMLInputElement
    expect(input.value).toBe('2024-02-01')
  })

  it('does not render anything when open is false', () => {
    const { container } = render(
      <ReschedulePopover
        repair={createRepair()}
        open={false}
        onConfirm={vi.fn()}
        onCancel={vi.fn()}
      />,
    )
    expect(container.innerHTML).toBe('')
  })
})

// ---------------------------------------------------------------------------
// Tests: Cancel behavior
// ---------------------------------------------------------------------------

describe('ReschedulePopover — cancel', () => {
  it('calls onCancel when cancel button is clicked', () => {
    const mockCancel = vi.fn()
    renderPopover(createRepair(), { onCancel: mockCancel })

    fireEvent.click(screen.getByText(/cancel/i))
    expect(mockCancel).toHaveBeenCalledOnce()
  })

  it('does not call API on cancel', async () => {
    renderPopover(createRepair())
    fireEvent.click(screen.getByText(/cancel/i))

    await waitFor(() => {
      expect(mockUpdateRepairNotes).not.toHaveBeenCalled()
    }, { timeout: 500 })
  })
})

// ---------------------------------------------------------------------------
// Tests: Confirm behavior
// ---------------------------------------------------------------------------

describe('ReschedulePopover — confirm', () => {
  it('sends PATCH with new plannedDate when date is changed and confirmed', async () => {
    const mockConfirm = vi.fn()
    const repair = createRepair({ id: 'repair-001' })

    mockUpdateRepairNotes.mockResolvedValueOnce(repair)

    renderPopover(repair, { onConfirm: mockConfirm })

    // Change the date input to Feb 5, 2024
    const input = screen.getByRole('textbox') as HTMLInputElement
    fireEvent.change(input, { target: { value: '2024-02-05' } })

    fireEvent.click(screen.getByText(/confirm/i))

    await waitFor(() => {
      expect(mockUpdateRepairNotes).toHaveBeenCalledWith(
        'repair-001',
        expect.objectContaining({ plannedDate: expect.any(Number) }),
      )
    })
  })

  it('calls onConfirm after successful API call', async () => {
    const mockConfirm = vi.fn()
    const repair = createRepair({ id: 'repair-001' })

    mockUpdateRepairNotes.mockResolvedValueOnce(repair)

    renderPopover(repair, { onConfirm: mockConfirm })

    // Change date and confirm
    const input = screen.getByRole('textbox') as HTMLInputElement
    fireEvent.change(input, { target: { value: '2024-02-10' } })
    fireEvent.click(screen.getByText(/confirm/i))

    await waitFor(() => {
      expect(mockConfirm).toHaveBeenCalledOnce()
    })
  })

  it('does not call onConfirm when date is unchanged', async () => {
    const mockConfirm = vi.fn()
    renderPopover(createRepair(), { onConfirm: mockConfirm })

    // Don't change the date, just click confirm
    fireEvent.click(screen.getByText(/confirm/i))

    await waitFor(() => {
      expect(mockConfirm).not.toHaveBeenCalled()
    }, { timeout: 500 })
  })

  it('does not call API when date is unchanged', async () => {
    renderPopover(createRepair())

    fireEvent.click(screen.getByText(/confirm/i))

    await waitFor(() => {
      expect(mockUpdateRepairNotes).not.toHaveBeenCalled()
    }, { timeout: 500 })
  })
})

/**
 * ReschedulePopover — Compact inline date picker for rescheduling a repair.
 *
 * Renders an absolute-positioned popover with:
 * - Date input pre-filled with the repair's anchor date (plannedDate or createdAt)
 * - Confirm button that PATCHes plannedDate via updateRepairNotes API
 * - Cancel button that closes without saving
 *
 * The caller controls `open` state and provides callbacks for confirm/cancel.
 */

import { useState, useEffect } from 'react'
import type { RepairDetailWithCustomer } from '../types.js'
import { getDateAnchor } from '../utils/dateAnchor.js'
import { updateRepairNotes } from '../api.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface ReschedulePopoverProps {
  repair: RepairDetailWithCustomer
  open: boolean
  onConfirm: () => void
  onCancel: () => void
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Convert epoch-ms to YYYY-MM-DD string for HTML date input */
function epochToDateInput(epochMs: number): string {
  const d = new Date(epochMs)
  return d.toISOString().split('T')[0]
}

/** Parse YYYY-MM-DD from date input to epoch-ms (start of day, local time) */
function dateInputToEpoch(value: string): number | null {
  if (!value) return null
  const parts = value.split('-')
  if (parts.length !== 3) return null
  // Create date in local timezone to avoid UTC shift issues
  const year = parseInt(parts[0], 10)
  const month = parseInt(parts[1], 10) - 1 // JS months are 0-indexed
  const day = parseInt(parts[2], 10)
  const d = new Date(year, month, day)
  if (isNaN(d.getTime())) return null
  return d.getTime()
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function ReschedulePopover({ repair, open, onConfirm, onCancel }: ReschedulePopoverProps) {
  const anchorEpoch = getDateAnchor({ plannedDate: repair.plannedDate, createdAt: repair.createdAt })
  const [dateValue, setDateValue] = useState<string>(epochToDateInput(anchorEpoch))
  const [isSaving, setIsSaving] = useState(false)

  // Reset date value when the popover opens or repair changes
  useEffect(() => {
    if (open) {
      const currentAnchor = getDateAnchor({ plannedDate: repair.plannedDate, createdAt: repair.createdAt })
      setDateValue(epochToDateInput(currentAnchor))
      setIsSaving(false)
    }
  }, [open, repair.id, repair.plannedDate, repair.createdAt])

  if (!open) return null

  const originalEpoch = getDateAnchor({ plannedDate: repair.plannedDate, createdAt: repair.createdAt })
  const newEpoch = dateInputToEpoch(dateValue)
  const hasChanged = newEpoch !== null && newEpoch !== originalEpoch

  const handleConfirm = async () => {
    if (!hasChanged || !newEpoch) return

    setIsSaving(true)
    try {
      await updateRepairNotes(repair.id, { plannedDate: newEpoch })
      onConfirm()
    } catch {
      // Silently fail — user can retry. In production, show a toast.
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <div className="absolute z-50 mt-1 w-[220px] rounded-lg border bg-popover p-3 shadow-lg">
      <div className="space-y-2">
        {/* Date Input */}
        <div>
          <label className="block text-xs font-medium text-muted-foreground mb-1">
            New planned date
          </label>
          <input
            type="date"
            value={dateValue}
            onChange={(e) => setDateValue(e.target.value)}
            className="w-full px-2 py-1.5 text-sm border rounded-md bg-background focus:outline-none focus:ring-2 focus:ring-ring"
          />
        </div>

        {/* Buttons */}
        <div className="flex gap-2 justify-end">
          <button
            type="button"
            onClick={onCancel}
            disabled={isSaving}
            className="px-3 py-1.5 text-xs font-medium rounded-md border hover:bg-muted transition-colors disabled:opacity-50"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={handleConfirm}
            disabled={!hasChanged || isSaving}
            className="px-3 py-1.5 text-xs font-medium rounded-md bg-primary text-primary-foreground hover:bg-primary/90 transition-colors disabled:opacity-50"
          >
            {isSaving ? 'Saving...' : 'Confirm'}
          </button>
        </div>
      </div>
    </div>
  )
}

