/**
 * RepairCalendarView — Component tests.
 *
 * Verifies:
 * - Renders 7 day columns (Mon–Sun)
 * - Week navigation header with prev/today/next buttons and week label
 * - Distributes repairs into correct day columns by date anchor
 * - Empty day columns show nothing
 * - Uses useRepairsForWeek hook for data
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, fireEvent } from '@testing-library/react'
import { MemoryRouter } from 'react-router-dom'
import type { RepairDetailWithCustomer } from '../../types.js'

// ---------------------------------------------------------------------------
// Mock the hook — must be at top level for hoisting
// ---------------------------------------------------------------------------

const mockUseRepairsForWeek = vi.fn() as ReturnType<typeof vi.fn> & {
  mockReturnValue: (value: unknown) => void
}

vi.mock('../../hooks/useRepairsForWeek.js', () => ({
  useRepairsForWeek: (...args: unknown[]) => mockUseRepairsForWeek(...args),
}))

// ---------------------------------------------------------------------------
// Test fixtures
// ---------------------------------------------------------------------------

function createRepair(id: string, plannedDate: number | null): RepairDetailWithCustomer {
  return {
    id,
    assignedTo: null,
    status: 'in_progress',
    customerNotes: null,
    internalNotes: null,
    holdReason: null,
    holdReasonNote: null,
    plannedDate,
    pickupDate: null,
    completedAt: null,
    createdAt: TUESDAY, // Feb 6 — within the test week for fallback placement
    customerName: 'Test Customer',
    bicycleBrand: 'Trek',
    bicycleModel: 'Domane',
    bicycleColor: 'blue',
  }
}

// Feb 2024 week: Mon Feb 5 — Sun Feb 11
const WEEK_MONDAY = 1707033600000 // Feb 5, 2024 00:00 UTC+1 approx
const TUESDAY = 1707120000000     // Feb 6
const WEDNESDAY = 1707206400000   // Feb 7

// ---------------------------------------------------------------------------
// Helper — set up the mock hook return value and render
// ---------------------------------------------------------------------------

function setupHook(repairs: RepairDetailWithCustomer[], isLoading = false) {
  const mockGoPrev = vi.fn()
  const mockGoNext = vi.fn()
  const mockGoToday = vi.fn()

  mockUseRepairsForWeek.mockReturnValue({
    repairs,
    weekStart: WEEK_MONDAY,
    weekEnd: WEEK_MONDAY + 6 * 24 * 60 * 60 * 1000 + 86399999,
    isLoading,
    error: null,
    goPrev: mockGoPrev,
    goNext: mockGoNext,
    goToday: mockGoToday,
  })

  return { mockGoPrev, mockGoNext, mockGoToday }
}

// ---------------------------------------------------------------------------
// Tests: Day columns rendering
// ---------------------------------------------------------------------------

describe('RepairCalendarView — day columns', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    setupHook([])
  })

  it('renders 7 day columns (Mon–Sun)', async () => {
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )
    const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
    for (const day of days) {
      expect(screen.getByText(day)).toBeInTheDocument()
    }
  })

  it('renders empty columns without placeholder cards', async () => {
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )
    // Should not find any repair cards when no repairs exist
    expect(screen.queryByText(/Test Customer/)).not.toBeInTheDocument()
  })
})

// ---------------------------------------------------------------------------
// Tests: Week navigation header
// ---------------------------------------------------------------------------

describe('RepairCalendarView — week navigation', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    setupHook([])
  })

  it('renders prev/next/today buttons and week label', async () => {
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )
    expect(screen.getByRole('button', { name: /previous/i })).toBeInTheDocument()
    expect(screen.getByRole('button', { name: /today/i })).toBeInTheDocument()
    expect(screen.getByRole('button', { name: /next/i })).toBeInTheDocument()
  })

  it('calls goPrev when prev button is clicked', async () => {
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    const { mockGoPrev } = setupHook([])
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )
    const prevBtn = screen.getByRole('button', { name: /previous/i })
    fireEvent.click(prevBtn)
    expect(mockGoPrev).toHaveBeenCalled()
  })

  it('calls goNext when next button is clicked', async () => {
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    const { mockGoNext } = setupHook([])
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )
    const nextBtn = screen.getByRole('button', { name: /next/i })
    fireEvent.click(nextBtn)
    expect(mockGoNext).toHaveBeenCalled()
  })

  it('calls goToday when today button is clicked', async () => {
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    const { mockGoToday } = setupHook([])
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )
    const todayBtn = screen.getByRole('button', { name: /today/i })
    fireEvent.click(todayBtn)
    expect(mockGoToday).toHaveBeenCalled()
  })
})

// ---------------------------------------------------------------------------
// Tests: Repair distribution into day columns
// ---------------------------------------------------------------------------

describe('RepairCalendarView — repair distribution', () => {
  beforeEach(() => {
    vi.clearAllMocks()
  })

  it('distributes repairs to correct day column by plannedDate', async () => {
    const repairs = [
      createRepair('r1', TUESDAY),   // Feb 6 — Tuesday
      createRepair('r2', WEDNESDAY), // Feb 7 — Wednesday
    ]

    setupHook(repairs)
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )

    // Both repairs should be visible in the calendar
    expect(screen.getAllByText(/Test Customer/)).toHaveLength(2)
  })

  it('uses createdAt as fallback when plannedDate is null', async () => {
    const repair = createRepair('r1', null)

    setupHook([repair])
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )

    expect(screen.getByText(/Test Customer/)).toBeInTheDocument()
  })
})

// ---------------------------------------------------------------------------
// Tests: Loading state
// ---------------------------------------------------------------------------

describe('RepairCalendarView — loading state', () => {
  it('shows loading indicator when isLoading is true', async () => {
    setupHook([], true)
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )
    expect(screen.getByRole('status')).toBeInTheDocument()
  })
})

